/// The published variables (`sce:direction="out"`) as one owned value, in
/// declaration order.
#[derive(Debug, Clone, PartialEq)]
#[allow(non_snake_case)]
pub struct StaticHostModelData {
    pub calls: u32,
    pub outcome: ::sce_rust_runtime::portable::SceString<24>,
    pub finish: ::sce_rust_runtime::portable::SceString<16>,
    pub constrained: bool,
    pub answered_by: ::sce_rust_runtime::portable::SceString<128>,
    pub prompt_tokens: u32,
    pub answer_tokens: u32,
    pub answer: Option<StaticHostModelAnswerRecord>,
    pub why: Option<StaticHostModelLiftRefusalRecord>,
}

/// What a host observes: the full active configuration — every active state,
/// each region of a `<parallel>` included — and the published variables,
/// taken together between two host calls, which is a macrostep boundary (W3C
/// SCXML Appendix D). `truncated` is `true` when that macrostep was stopped at
/// the microstep ceiling, so the configuration is not a stable one. Owned: a
/// host holding one keeps what it saw whatever the machine does next.
#[derive(Debug, Clone, PartialEq)]
pub struct StaticHostModelSnapshot {
    pub configuration: StaticHostModelConfiguration,
    pub data: StaticHostModelData,
    pub truncated: bool,
}

/// The snapshot of a running machine, as an extension of the runtime's
/// `Engine` (a foreign type, so a local trait — the `Inject` shape).
pub trait StaticHostModelObserve {
    /// The machine as the host sees it now: one [`StaticHostModelSnapshot`],
    /// never a state between two microsteps.
    fn snapshot(&self) -> StaticHostModelSnapshot;
}

impl StaticHostModelObserve for Engine<StaticHostModelPolicy> {
    fn snapshot(&self) -> StaticHostModelSnapshot {
        let policy = self.policy();
        StaticHostModelSnapshot {
            configuration: self.get_active_states(),
            data: StaticHostModelData {
                calls: policy.calls,
                outcome: policy.outcome.clone(),
                finish: policy.finish.clone(),
                constrained: policy.constrained,
                answered_by: policy.answered_by.clone(),
                prompt_tokens: policy.prompt_tokens,
                answer_tokens: policy.answer_tokens,
                answer: policy.answer.clone(),
                why: policy.why.clone(),
            },
            truncated: self.last_macrostep_truncated(),
        }
    }
}

